function geoHasPoint(geo,lat,lng){if(!geo)return false;const ringHas=ring=>inPoly([lat,lng],ring.map(p=>[p[1],p[0]]));const polygonHas=poly=>!!poly?.[0]&&ringHas(poly[0])&&!poly.slice(1).some(ringHas);const g=geo.type==="Feature"?geo.geometry:geo;if(!g)return false;if(g.type==="Polygon")return polygonHas(g.coordinates);if(g.type==="MultiPolygon")return g.coordinates.some(polygonHas);if(g.type==="FeatureCollection")return g.features.some(f=>geoHasPoint(f,lat,lng));return false}
