async function applySelectedArea(){if(!st.areaRegion){uiAlert("Avval viloyatni tanlang.","Hudud tanlanmagan");return}const selected=st.areaDistrict||st.areaRegion;const query=(st.areaDistrict?selected+", "+st.areaRegion:st.areaRegion)+", Uzbekistan";const status=$("myLocStatus");if(status)status.textContent="Hudud chegarasi yuklanmoqda…";try{const url="https://nominatim.openstreetmap.org/search?format=jsonv2&polygon_geojson=1&limit=8&q="+encodeURIComponent(query);const res=await fetch(url,{headers:{Accept:"application/json"}});if(!res.ok)throw new Error("Xarita xizmati javob bermadi");const data=await res.json();const candidates=data.filter(x=>x.geojson&&["Polygon","MultiPolygon"].includes(x.geojson.type));const place=st.areaDistrict?pl(st.areaDistrict):null;const regionPlaces=(PL.find(x=>x[0]===st.areaRegion)||[null,[]])[1];const targetLat=place?place.lat:regionPlaces.reduce((sum,p)=>sum+p[1],0)/Math.max(1,regionPlaces.length);const targetLng=place?place.lng:regionPlaces.reduce((sum,p)=>sum+p[2],0)/Math.max(1,regionPlaces.length);const center=x=>{const pts=[];const walk=v=>{if(Array.isArray(v)&&typeof v[0]==="number")pts.push(v);else if(Array.isArray(v))v.forEach(walk)};walk(x.geojson.coordinates);if(!pts.length)return [0,0];return [(Math.min(...pts.map(p=>p[1]))+Math.max(...pts.map(p=>p[1])))/2,(Math.min(...pts.map(p=>p[0]))+Math.max(...pts.map(p=>p[0])))/2]};const norm=s=>String(s||"").toLowerCase().trim();const target=norm(selected);const found=candidates.find(x=>norm(x.name)===target)||candidates.find(x=>norm(x.display_name).includes(target))||candidates.sort((a,b)=>{const aa=center(a),bb=center(b);return distanceKm(targetLat,targetLng,aa[0],aa[1])-distanceKm(targetLat,targetLng,bb[0],bb[1])})[0];if(!found)throw new Error("Bu hududning aniq chegarasi topilmadi. Boshqa nom bilan qayta tanlang.");st.areaGeo={type:"Feature",properties:{name:found.name||selected},geometry:found.geojson};st.areaLabel=selected;st.dr={on:false,pts:[]};st.mv=null;st.mz=st.areaDistrict?10:7;draw();setTimeout(()=>{if(MAP&&st.areaGeo){const layer=L.geoJSON(st.areaGeo);MAP.fitBounds(layer.getBounds(),{padding:[20,20],maxZoom:st.areaDistrict?12:8})}},250)}catch(e){if(status)status.textContent=e.message||"Hudud chegarasini yuklab boʻlmadi.";uiAlert((e.message||"Hudud chegarasini yuklab boʻlmadi.")+" Internetni tekshiring yoki boshqa hududni tanlang.","Hudud chizilmadi")}}
