function groupsV(){if(!st.user)return needLogin("Guruhlar");const mine=st.user.groups||[];const sorted=[...st.groups].sort((a,b)=>(Number(b.premiumUntil)>Date.now()?1:0)-(Number(a.premiumUntil)>Date.now()?1:0)||(b.t||0)-(a.t||0));return `<h3>Guruhlar</h3><p class="sub" style="text-align:left">Ochiq guruhga darhol qoʻshiling yoki anonim guruhga kirish uchun egasidan ruxsat oling. Premium guruhlar roʻyxatda yuqoriroq koʻrinadi.</p><button class="go" style="width:100%;margin-bottom:10px" onclick="newGroup()">${I("plus",16)} Yangi guruh ochish</button>`+(sorted.map(g=>`<div class="card"><div class="av">${esc(g.ava||"👥")}</div><div class="inf"><b>${esc(g.name)} ${g.premiumUntil>Date.now()?'<span class="tag vt">PREMIUM</span>':''}</b><p>${I("users",14)} ${g.n||1} aʼzo · ${g.visibility==="open"?"Ochiq guruh":"Anonim guruh"}</p><p class="sub">${g.visibility==="open"?"Hamma darhol qoʻshila oladi":"Qoʻshilish uchun egasi tasdigʻi kerak"}</p>${g.premiumUntil>Date.now()?'<p class="sub">Premium tugaydi: '+new Date(g.premiumUntil).toLocaleDateString("uz")+'</p>':""}<div class="acts"><button class="go" onclick="${mine.includes(g.id)?`openG('${g.id}')`:`joinG('${g.id}')`}">${mine.includes(g.id)?"Chatga kirish":"Qoʻshilish"}</button>${st.admin&&!mine.includes(g.id)?`<button class="ghost" onclick="observeG('${g.id}')">Kuzatish</button>`:""}</div></div></div>`).join("")||'<div class="empty">Hozircha guruh yoʻq. Birinchi boʻlib oching!</div>')}
