function chatMsgs(){const m=$("ms");if(!m)return;const g=st.chat.t=="g",now=Date.now();st.mediaUrls=st.mediaUrls||{};st.mediaLoading=st.mediaLoading||{};const visible=st.cm.filter(x=>(!x.visibleAt||Number(x.visibleAt)<=now)&&(!x.expiresAt||Number(x.expiresAt)>now));m.innerHTML=(typeof olderBtn=="function"?olderBtn():"")+visible.map(x=>{if(x.deleted&&typeof deletedBubble=="function")return deletedBubble(x,g);if(x.kind=="like")return `<div class="m ${x.from==st.user.uid?"me":""}"><span style="color:var(--r)">${I("heart",24,1)}</span> ${esc(String(x.text).replace("❤️ ",""))}<small>${tm(x.t)}</small></div>`;if((x.kind=="callreq"||x.kind=="callok")&&typeof callReqBubble=="function")return callReqBubble(x);if(x.kind=="call"&&typeof callBubble=="function")return callBubble(x);if(x.kind=="voice"&&typeof voiceBubble=="function")return voiceBubble(x,g);if(x.kind=="sticker")return `<div class="m stk ${x.from==st.user.uid?"me":""}" data-mid="${x.id}">${g&&x.from!=st.user.uid?`<b>${esc(x.name||"")}</b>`:""}${typeof replyQuote=="function"?replyQuote(x):""}<span class="stk-e">${esc(x.text)}</span><small>${tm(x.t)}${typeof msgTick=="function"?msgTick(x):""}</small></div>`;let body=esc(x.text);if(x.kind==="media"&&x.mediaPath){const url=st.mediaUrls[x.id];if(url)body=x.mediaType==="video"?`<video controls playsinline preload="metadata" onerror="console.warn('Video ochilmadi:',this.src)" style="display:block;width:min(100%,300px);max-height:360px;border-radius:12px" src="${url}"></video>`:`<img loading="lazy" alt="Yuborilgan rasm" onclick="zoom(this.src)" onerror="console.warn('Media ochilmadi:',this.src);this.replaceWith(Object.assign(document.createElement('a'),{href:this.src,target:'_blank',rel:'noopener',textContent:'Rasm ochilmadi. Bosib koʻring.'}))" src="${url}" style="display:block;width:min(100%,300px);max-height:360px;object-fit:contain;border-radius:12px">`;else{body='<small>Media yuklanmoqda…</small>';if(!st.mediaLoading[x.id]){st.mediaLoading[x.id]=true;FB.groupMediaBlob(x.mediaPath,x.mediaProvider,x.mediaUrl).then(u=>{st.mediaUrls[x.id]=u;delete st.mediaLoading[x.id];if(st.chat&&st.cm.some(y=>y.id===x.id))chatMsgs()}).catch(()=>{delete st.mediaLoading[x.id];const node=$("ms");if(node){const z=[...node.querySelectorAll(".m")],idx=st.cm.findIndex(y=>y.id===x.id);if(z[idx])z[idx].insertAdjacentHTML("beforeend",'<small>Media yuklanmadi (ruxsat yoki internetni tekshiring).</small>')}})}}}return `<div class="m ${x.from==st.user.uid?"me":""}" data-mid="${x.id}">${g&&x.from!=st.user.uid?`<b>${esc(x.name||"")}</b>`:""}${typeof replyQuote=="function"?replyQuote(x):""}${body}<small>${tm(x.t)}${typeof msgTick=="function"?msgTick(x):""}</small></div>`}).join("");m.scrollTop=m.scrollHeight;if(st.keepScroll){m.scrollTop=m.scrollHeight-st.keepScroll.h+st.keepScroll.t;st.keepScroll=null}if(typeof voiceRestore=="function")voiceRestore();if(typeof liveRender=="function")liveRender();if(st.scheduleTimer)clearTimeout(st.scheduleTimer);st.scheduleTimer=setTimeout(()=>{if(st.chat&&st.chat.t==="g")chatMsgs()},30000)}
