function legalV(){const L=st.lg||{};return `<div class="ov"><div class="hd"><button onclick="st.form='admin';draw()">${I("back",22)}</button><b>Rasmiy soʻrovlar</b></div><div class="sheet"><div class="price"><p class="sub" style="text-align:left">Vakolatli davlat organining qonunga muvofiq yozma soʻrovi boʻyicha foydalanuvchining hisob maʼlumotlarini (profil, eʼlonlar, toʻlovlar, shikoyatlar, guruh aʼzoligi) tayyorlash. Shaxsiy yozishmalar mazmuni bu orqali berilmaydi. Har bir amal oʻzgartirib boʻlmaydigan jurnalga yoziladi.</p></div><label>Organ nomi</label><input class="in" id="lga" maxlength="120"><label>Soʻrov raqami va sanasi</label><input class="in" id="lgn" maxlength="80"><label>Huquqiy asos (qisqacha)</label><input class="in" id="lgb" maxlength="300"><label>Foydalanuvchi: UID, telefon yoki email</label><input class="in" id="lgt"><button class="go" style="width:100%;margin-top:14px" onclick="legalRun()">Maʼlumotni tayyorlash (JSON)</button><h3 style="margin-top:18px">Jurnal</h3>${(L.log||[]).map(x=>`<div class="card"><div class="inf"><b>${esc(x.agency)}</b><p>${esc(x.refNo)} · ${new Date(x.t).toLocaleString("uz")}</p><p>${esc(x.targetUid)}</p></div></div>`).join("")||'<div class="empty">Jurnal boʻsh</div>'}</div></div>`}
async function legalRun(){const g=id=>($(id)?.value||"").trim(),m={agency:g("lga"),refNo:g("lgn"),basis:g("lgb")},t=g("lgt");if(!m.agency||!m.refNo||!m.basis||!t){uiAlert("Barcha maydonlarni toʻldiring");return}if(!await uiConfirm("Faqat vakolatli organning rasmiy yozma soʻrovi asosida. Amal jurnalga yoziladi. Davom etamizmi?","Tayyorlash"))return;try{const r=await FB.legalExport(t,m),b=new Blob([JSON.stringify(r,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="rasmiy-sorov-"+Date.now()+".json";document.body.appendChild(a);a.click();a.remove();toast("Fayl tayyorlandi");FB.auditList().then(l=>{st.lg.log=l;draw()}).catch(()=>{})}catch(x){uiAlert(x.message||x)}}
async function changeGroupCover(){const ch=st.chat;if(!ch||ch.t!=="g")return;const g=st.groups.find(x=>x.id===ch.id);if(!g||g.owner!==st.user.uid){uiAlert("Faqat guruh egasi asosiy rasmni oʻzgartira oladi.");return}const input=document.createElement("input");input.type="file";input.accept="image/*";input.onchange=()=>{const file=input.files&&input.files[0];if(!file)return;if(file.size>8*1024*1024){uiAlert("Rasm 8 MB dan kichik boʻlsin.");return}const reader=new FileReader();reader.onload=async()=>{try{const im=new Image();im.onload=async()=>{try{const c=document.createElement("canvas");c.width=700;c.height=700;const scale=Math.max(700/im.width,700/im.height),w=im.width*scale,h=im.height*scale;c.getContext("2d").drawImage(im,(700-w)/2,(700-h)/2,w,h);const data=c.toDataURL("image/jpeg",.84);const url=await FB.setGroupCover(ch.id,data);g.ava=url;st.menu=false;draw();toast("Guruh rasmi yangilandi")}catch(e){uiAlert("Rasm oʻzgartirilmadi: "+(e.message||e))}};im.onerror=()=>uiAlert("Rasmni ochib boʻlmadi");im.src=reader.result}catch(e){uiAlert(e.message||e)}};reader.readAsDataURL(file)};input.click()}
