const GM_COMPRESS=async f=>{if(!/^image\/(jpeg|png|webp|heic|heif)$/.test(f.type)||f.size<400*1024)return f;try{const bmp=await createImageBitmap(f),sc=Math.min(1,2048/Math.max(bmp.width,bmp.height)),w=Math.round(bmp.width*sc),h=Math.round(bmp.height*sc),c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(bmp,0,0,w,h);const blob=await new Promise(r=>c.toBlob(r,"image/jpeg",.85));if(blob&&blob.size<f.size)return new File([blob],(f.name||"rasm").replace(/\.[^.]+$/,"")+".jpg",{type:"image/jpeg"})}catch(e){}return f};
