async function uploadGroupMedia(input){let file=input.files&&input.files[0];if(!file)return;if(st.uploadingMedia){uiAlert("Oldingi media hali yuklanmoqda. Biroz kuting.");input.value="";return}input.value="";const ch=st.chat;if(!ch||ch.t!=="g")return;if(!/^image\//.test(file.type)&&!["video/mp4","video/webm","video/quicktime"].includes(file.type)){uiAlert("Faqat rasm yoki MP4/WebM/MOV video yuborish mumkin.");return}if(/^image\//.test(file.type)){upStatus("Rasm tayyorlanmoqda…");file=await GM_COMPRESS(file);upStatus(null)}const g=st.groups.find(x=>x.id===ch.id),premium=!!g&&Number(g.premiumUntil)>Date.now(),video=file.type.startsWith("video/"),max=video?(premium?50:20)*1024*1024:(premium?25:5)*1024*1024;if(file.size>max){uiAlert(video?"Video "+(premium?"50 MB":"20 MB")+" dan kichik boʻlishi kerak.":"Rasm "+(premium?"25 MB":"5 MB")+" dan kichik boʻlishi kerak.");return}let meta={};try{meta=premium?scheduleMeta():{};const secs=Number($("disappearAfter")?.value||0);if(secs>0&&!video)meta.expiresAt=Date.now()+secs*1000;else if(secs>0&&video){uiAlert("Oʻzi yoʻqoladigan rejim hozircha faqat rasmlar uchun.");return}}catch(e){uiAlert(e.message||String(e));return}st.uploadingMedia=true;upStatus((video?"Video":"Rasm")+" yuklanmoqda… 0%");try{await FB.uploadGroupMedia(ch.id,file,meta,p=>upStatus((video?"Video":"Rasm")+" yuklanmoqda… "+Math.round(p*100)+"%"));upStatus(null);toast("Media yuborildi");if($("scheduleVisible"))$("scheduleVisible").value="";if($("scheduleExpires"))$("scheduleExpires").value=""}catch(e){upStatus(null);uiAlert("Media yuborilmadi: "+(e.message||e))}finally{st.uploadingMedia=false;upStatus(null)}}
