async function startGroupPremiumPayment(){const ch=st.chat;if(!ch||ch.t!=="g")return;const group=st.groups.find(x=>x.id===ch.id);if(!group||(group.owner!==st.user.uid&&!st.admin)){uiAlert("Faqat guruh egasi premiumni boshqarishi mumkin.");return}if(st.admin){const act=group.premiumUntil>Date.now();if(!await uiConfirm("Admin sifatida premium bepul: "+(act?"yana 30 kunga uzaytirilsinmi?":"30 kunga yoqilsinmi?"),"Premium"))return;try{await FB.adminSetGroupPremium(ch.id,Math.max(Date.now(),Number(group.premiumUntil)||0)+30*864e5);st.form=null;draw();toast("Premium yoqildi (admin, bepul)")}catch(e){uiAlert(e.message||e)}return}if(st.mypays.some(p=>p.kind==="group_premium"&&p.groupId===ch.id&&p.status==="pending")){uiAlert("Bu guruh uchun premium soʻrovi allaqachon yuborilgan. Admin tekshiruvini kuting.");return}const active=group.premiumUntil>Date.now();if(!await uiConfirm("30 000 soʻm toʻlab, premiumni "+(active?"yana 30 kunga uzaytirish":"30 kunga yoqish")+" uchun toʻlov soʻrovi yuborilsinmi?","Premium guruh"))return;try{const id=await FB.pay({kind:"group_premium",groupId:ch.id,amount:30000},st.user);st.form=null;draw();paySheet(30000,id,active?"guruh premium muddatiga yana 30 kun qoʻshiladi":"guruhingizga 30 kunlik premium yoqiladi")}catch(e){uiAlert("Soʻrov yuborilmadi: "+(e.message||e))}}
async function deleteG(){const ch=st.chat;if(!ch||ch.t!=="g")return;const group=st.groups.find(x=>x.id===ch.id);if(!group||group.owner!==st.user.uid){uiAlert("Faqat guruhni ochgan odam uni oʻchira oladi.");return}if(!await uiConfirm("«"+group.name+"» guruhini va uning xabarlarini butunlay oʻchirasizmi? Bu amalni qaytarib boʻlmaydi.","Guruhni oʻchirish",true))return;try{await FB.deleteGroup(ch.id);st.user.groups=(st.user.groups||[]).filter(x=>x!==ch.id);closeChat();toast("Guruh oʻchirildi")}catch(x){uiAlert("Guruh oʻchirilmadi: "+(x.message||x))}}
async function leaveG(){const id=st.chat.id;if(!await uiConfirm("Guruhdan chiqasizmi?","Chiqish",true))return;try{await FB.leaveGroup(id);st.user.groups=(st.user.groups||[]).filter(x=>x!=id);closeChat()}catch(x){uiAlert(x.message)}}
async function grant(on){const id=st.chat.id;st.menu=false;try{const cc=st.chats.find(x=>x.id==id),ok=await FB.grant(id,on,cc&&cc.adId);if(!ok)uiAlert("Avval Profil boʻlimida shaxsiy rasmlaringizni yuklang (3 tagacha).","Rasm yoʻq");draw()}catch(x){uiAlert("Amal bajarilmadi: "+x.message)}}
const RP_REASONS=["Soxta yoki yolgʻon eʼlon","Nomaʼqul yoki haqoratli rasm","Haqorat, tahdid yoki bezovtalik","Reklama yoki spam","Aldamchilik, pul soʻrash","Boshqa sabab"];
function rpSheet(kind,id){const o=document.createElement("div");o.className="rp-bg";o.onclick=()=>o.remove();o.innerHTML=`<div class="rp" onclick="event.stopPropagation()"><b>Shikoyat sababi</b><small>Admin shikoyatni koʻrib chiqadi. Shikoyat qilganingiz sir saqlanadi.</small>${RP_REASONS.map((x,i)=>`<button type="button" data-i="${i}">${esc(x)}</button>`).join("")}<button type="button" class="cn">Bekor qilish</button></div>`;o.querySelectorAll("button[data-i]").forEach(b=>b.onclick=()=>{o.remove();rpSend(kind,id,RP_REASONS[+b.dataset.i])});o.querySelector(".cn").onclick=()=>o.remove();document.body.appendChild(o)}
async function rpSend(kind,id,reason){const f=fb();if(!f)return;try{if(kind=="ad"){const a=st.ads.find(x=>x.id==id);if(!a)return;await f.reportAd(a,reason)}else await f.report(id,reason);toast("Shikoyatingiz yuborildi")}catch(x){uiAlert("Yuborilmadi: "+x.message)}}
function reportAd(id){if(!need())return;const a=st.ads.find(x=>x.id==id);if(!a)return;if(a.uid==st.user.uid){uiAlert("Bu sizning oʻz eʼloningiz");return}rpSheet("ad",id)}
function report(){st.menu=false;draw();if(st.chat)rpSheet("chat",st.chat.id)}
function zoom(s){const d=document.createElement("div");d.className="md";d.innerHTML=`<img src="${s}" style="max-width:100%;max-height:80vh;border-radius:16px">`;d.onclick=()=>d.remove();document.body.appendChild(d)}
function chatV(){const ch=st.chat,g=ch.t=="g",c=g?st.groups.find(x=>x.id==ch.id):st.chats.find(x=>x.id==ch.id);
 if(!c)return `<div class="ov"><div class="hd"><button onclick="closeChat()">${I("back",22)}</button><b>Yuklanmoqda...</b></div></div>`;
 const me=st.user.uid,own=!g&&c.owner==me,asker=!g&&!own,groupOwner=g&&c.owner==me,canGroupMedia=g&&(groupOwner||c.mediaUploadMode==="members"),premiumActive=g&&Number(c.premiumUntil)>Date.now();
 const title=g?c.name:(own?c.askerName:((st.csh&&st.csh.name)||c.ownerName)),av=g?esc(c.ava||"👥"):(own?ava(c.askerImg):ava(c.ownerImg,c.ownerAva));
 let menu="";if(st.menu)menu=`<div class="menu">${g&&groupOwner?`<button onclick="changeGroupCover()">${I("cam",16)} Guruh asosiy rasmini oʻzgartirish</button>`:""}${own?(c.photoOk?`<button onclick="grant(false)">${I("lock",16)} Ruxsatni bekor qilish</button>`:`<button onclick="grant(true)">${I("img",16)} Shaxsiy rasmlarga ruxsat berish</button>`):""}${g?(c.owner==me?`<button onclick="toggleGroupVisibility()">${I("lock",16)} Guruh turi: ${c.visibility==="open"?"ochiq — anonim qilish":"anonim — ochish"}</button><button onclick="manageGroupRequests()">${I("users",16)} Qoʻshilish soʻrovlari</button><button onclick="setGroupMediaPolicy()">${I("img",16)} Media: ${c.mediaUploadMode==="members"?"aʼzolar ham yuklaydi":"faqat egasi yuklaydi"}</button><button onclick="requestGroupPremium()">${I("gift",16)} Premium haqida va ulash · 30 000 soʻm / 30 kun</button><button onclick="deleteG()" style="color:#e5554a">${I("x",16)} Guruhni oʻchirish</button>`:`${st.admin?`<button onclick="requestGroupPremium()">${I("gift",16)} Premium (admin, bepul)</button>`:""}<button onclick="report()">${I("flag",16)} Guruh haqida shikoyat</button><button onclick="leaveG()">${I("logout",16)} Guruhdan chiqish</button>`):`<button onclick="report()">${I("flag",16)} Shikoyat</button><button onclick="blockU()">${I("ban",16)} Bloklash</button>`}</div>`;
 const ban=own&&!c.photoOk&&!st.dis[c.id]&&st.cm.some(x=>x.from!=me)?`<div class="cons"><button class="x" onclick="st.dis['${c.id}']=1;draw()">${I("x",18)}</button><b>Shaxsiy rasm va maʼlumotlaringizni koʻrsatishga ruxsat berasizmi?</b><p style="color:var(--m);margin:4px 0 8px">Rasmlar faqat shu suhbatdosh uchun ochiladi. Istalgan payt bekor qilishingiz mumkin.</p><button class="go" onclick="grant(true)">Ruxsat berish</button></div>`:"";
 const ph=asker?(c.photoOk?`<div class="ph">${st.cph.map((x,i)=>`<img src="${x}" onclick="zoom('${x}')">`).join("")||'<small style="color:var(--m)">Yuklanmoqda...</small>'}</div>${st.csh&&st.csh.about?`<p class="sub" style="text-align:left;padding:8px 14px 0;margin:0">${esc(st.csh.about)}</p>`:""}`:`<div class="ph"><div class="lock">${I("lock",22)}</div><div class="lock">${I("lock",22)}</div><small style="color:var(--m);align-self:center">Shaxsiy rasmlar yopiq. Egasi ruxsat bersa ochiladi.</small></div>`):(own&&c.photoOk?`<div class="ph"><small style="color:var(--a)">${I("img",14)} Shaxsiy rasmlaringiz bu suhbatdoshga ochiq</small></div>`:"");
 return `<div class="ov"><div class="hd"><button onclick="closeChat()">${I("back",22)}</button><div class="av">${av}</div><b>${esc(title)}</b><button onclick="st.menu=!st.menu;draw()">${I("dots",20)}</button>${menu}</div>${ban}${ph}${premiumActive?`<div id="callControls" class="yaqin-call-controls"><div class="yaqin-call-head"><span class="yaqin-call-live-dot"></span><span id="callStatus" class="yaqin-call-status">${GC&&GC.gid===ch.id?"🎙️ Ovozli chat yoniq":st.groupCallRoom&&st.groupCallRoom.active?("Ovozli chat yoniq · "+(st.groupCallRoom.mode==="video"?"video ham yoqilgan":"aʼzolar ulanmoqda")):""}</span></div><div class="yaqin-call-actions">${GC&&GC.gid===ch.id?`<button class="yaqin-call-btn" id="callMuteBtn" type="button">🎙️ Mikrofonni oʻchirish</button><button class="yaqin-call-btn" id="callVideoBtn" type="button">${GC.videoTrack?"📷 Videoni oʻchirish":"📹 Videoni yoqish"}</button><button class="yaqin-call-btn yaqin-call-end" onclick="leaveGroupCall()" type="button">${typeof YI=="function"?YI("phone",18,"rot"):""} Tugatish</button>`:`<button class="yaqin-call-btn yaqin-call-primary" onclick="startGroupCall(this.dataset.mode)" data-mode="audio" type="button">${typeof YI=="function"?YI("mic",18):""} Ovozli chat</button><button class="yaqin-call-btn yaqin-call-video" onclick="startGroupCall(this.dataset.mode)" data-mode="video" type="button">${typeof YI=="function"?YI("video",18):""} Video translatsiya</button>`}</div></div><div id="groupCallPanel" class="yaqin-call-panel" style="display:${GC&&GC.gid===ch.id?"block":"none"}"><div id="callVideos" class="yaqin-call-videos"></div></div>`:""}<div class="msgs" id="ms"></div><div class="send${ch.obs?" obs":""}">${premiumActive?`<button class="ghost sch-t" type="button" title="Xabar vaqtini belgilash" aria-label="Xabar vaqtini belgilash" onclick="$(\'schRow\').classList.toggle(\'show\')">${I("clock",18)}</button><div class="sch-row" id="schRow"><label class="sch">Koʻrinish vaqti<input class="in" id="scheduleVisible" type="datetime-local"></label><label class="sch">Yashirish vaqti<input class="in" id="scheduleExpires" type="datetime-local"></label></div>`:""}<input class="in" id="mi" maxlength="1000" placeholder="Xabar yozing.." autocomplete="off" onkeydown="if(event.key=='Enter')send()">${canGroupMedia?`<select class="in disappear-select" id="disappearAfter" aria-label="Rasm qancha vaqtda yoʻqolsin" title="Yoʻqoladigan rasm muddati"><option value="0">Oddiy rasm</option><option value="10">10 soniya</option><option value="60">1 daqiqa</option><option value="3600">1 soat</option></select><input id="gmfile" type="file" accept="image/*,video/mp4,video/webm,video/quicktime" hidden onchange="uploadGroupMedia(this)"><button class="ghost media-attach" type="button" title="Rasm yoki video biriktirish" aria-label="Rasm yoki video biriktirish" onclick="$('gmfile').click()">${I("paperclip",18)}</button>`:""}<button class="go" onclick="send()">${I("send",18)}</button></div></div>`}

function callVideoNode(id,label,muted=false){const box=$("callVideos");if(!box)return null;let wrap=document.getElementById("call_"+id);if(!wrap){wrap=document.createElement("div");wrap.id="call_"+id;wrap.style.cssText="position:relative;min-height:100px;background:#171421;border-radius:12px;overflow:hidden";wrap.innerHTML='<video playsinline autoplay '+(muted?'muted ':'')+'style="width:100%;max-height:220px;object-fit:cover;display:block"></video><small style="display:block;padding:4px 6px;color:#fff"></small>';box.appendChild(wrap)}wrap.querySelector("small").textContent=label;return wrap.querySelector("video")}
function attachCallStream(id,stream,label,muted=false){const v=callVideoNode(id,label,muted);if(v&&v.srcObject!==stream){v.srcObject=stream;v.play().catch(()=>{})}}
function removeCallPeer(id){if(!GC)return;const p=GC.peers.get(id);if(p){p.unsub?.();p.pc.close();GC.peers.delete(id)}document.getElementById("call_"+id)?.remove()}
function makeCallPeer(remoteUid,signalId){if(!GC||GC.peers.has(remoteUid))return GC?.peers.get(remoteUid);const pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"},{urls:"stun:stun1.l.google.com:19302"}]});const p={pc,signalId,unsub:null,remoteReady:false,pending:[]};GC.peers.set(remoteUid,p);GC.stream.getTracks().forEach(t=>pc.addTrack(t,GC.stream));pc.onicecandidate=e=>{if(e.candidate&&GC)FB.groupCallAddCandidate(GC.gid,signalId,e.candidate,st.user.uid).catch(err=>console.warn("ICE yuborilmadi",err))};pc.ontrack=e=>{if(GC&&GC.gid===st.chat?.id){const stream=e.streams&&e.streams[0];if(stream)attachCallStream(remoteUid,stream,"Guruh aʼzosi "+remoteUid.slice(0,5));}};pc.onconnectionstatechange=()=>{if(["failed","closed"].includes(pc.connectionState))removeCallPeer(remoteUid)};p.unsub=FB.groupCallCandidates(GC.gid,signalId,items=>{for(const item of items){if(item.from===st.user.uid||p.seenCandidates?.has(item.id))continue;p.seenCandidates=p.seenCandidates||new Set();p.seenCandidates.add(item.id);try{const c=new RTCIceCandidate(item.candidate);if(p.remoteReady)pc.addIceCandidate(c).catch(()=>{});else p.pending.push(c)}catch(e){}}});return p}
async function makeCallOffer(remoteUid){if(!GC||GC.peers.has(remoteUid))return;const id=st.user.uid+"_"+remoteUid+"_"+Date.now()+"_"+Math.random().toString(36).slice(2,7),p=makeCallPeer(remoteUid,id),offer=await p.pc.createOffer();await FB.groupCallOffer(GC.gid,st.user.uid,remoteUid,offer,id);await p.pc.setLocalDescription(offer);await FB.groupCallSignalReady(GC.gid,id)}
async function handleCallOffer(sig){if(!GC||sig.caller===st.user.uid||!sig.offer||GC.peers.has(sig.caller))return;const p=makeCallPeer(sig.caller,sig.id);await p.pc.setRemoteDescription(new RTCSessionDescription(sig.offer));p.remoteReady=true;for(const c of p.pending.splice(0))await p.pc.addIceCandidate(c).catch(()=>{});const ans=await p.pc.createAnswer();await p.pc.setLocalDescription(ans);await FB.groupCallAnswer(GC.gid,sig.id,p.pc.localDescription)}
function startCallSignaling(){const uid=st.user.uid,gid=GC.gid;GC.unsubs.push(FB.groupCallParticipants(gid,ps=>{if(!GC||GC.gid!==gid)return;const active=new Set(ps.map(x=>x.uid));for(const peerUid of [...GC.peers.keys()])if(!active.has(peerUid))removeCallPeer(peerUid);for(const peer of ps){if(peer.uid===uid||GC.peers.has(peer.uid))continue;if(uid.localeCompare(peer.uid)>0)makeCallOffer(peer.uid).catch(e=>console.warn("Offer:",e))}}));GC.unsubs.push(FB.groupCallSignals(gid,"callee",uid,items=>{for(const sig of items)if(sig.offer&&sig.ready===true&&!GC?.handled?.has(sig.id)){GC.handled=GC.handled||new Set();GC.handled.add(sig.id);handleCallOffer(sig).catch(e=>{console.warn("Offer qabul qilinmadi",e);GC?.handled?.delete(sig.id)})}}));GC.unsubs.push(FB.groupCallSignals(gid,"caller",uid,items=>{for(const sig of items){const p=GC?.peers.get(sig.callee);if(p&&sig.answer&&!p.remoteReady){p.pc.setRemoteDescription(new RTCSessionDescription(sig.answer)).then(async()=>{p.remoteReady=true;for(const c of p.pending.splice(0))await p.pc.addIceCandidate(c).catch(()=>{})}).catch(e=>console.warn("Answer:",e))}}}))}
async function startGroupCall(mode){const ch=st.chat;if(!ch||ch.t!=="g")return;const g=st.groups.find(x=>x.id===ch.id);if(!g||Number(g.premiumUntil)<=Date.now()){uiAlert("Ovozli suhbat va jonli video uchun faol Premium guruh kerak.");return}if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection){uiAlert("Bu brauzerda mikrofon/kamera yoki WebRTC qoʻllab-quvvatlanmaydi. Saytni HTTPS orqali oching.");return}if(GC){if(GC.gid===ch.id&&GC.mode===mode)return uiAlert("Siz allaqachon qoʻngʻiroqdasiz.");await leaveGroupCall(true)}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==="video"?{facingMode:"user",width:{ideal:640},height:{ideal:480}}:false});GC={gid:ch.id,mode,stream,peers:new Map(),unsubs:[],handled:new Set()};await FB.groupCallEnter(ch.id,mode);draw();const panel=$("groupCallPanel");if(panel)panel.style.display="block";if(mode==="video")attachCallStream("local",stream,"Siz",true);else{const box=$("callVideos");if(box)box.innerHTML='<div style="padding:12px;background:var(--card);border-radius:10px">🎙️ Mikrofon faol. Boshqa aʼzolar ulanmoqda…</div>'}startCallSignaling();toast(mode==="video"?"Jonli video boshlandi":"Ovozli suhbat boshlandi")}catch(e){if(GC){GC.stream?.getTracks().forEach(t=>t.stop());GC.unsubs?.forEach(f=>f&&f());GC=null}uiAlert("Qoʻngʻiroq boshlanmadi: "+(e.message||e)+" . Mikrofon/kamera ruxsatini tekshiring.")}}
async function leaveGroupCall(silent=false){const old=GC;if(!old)return;GC=null;old.unsubs?.forEach(f=>{try{f&&f()}catch(e){}});old.peers?.forEach(p=>{try{p.unsub?.();p.pc.close()}catch(e){}});old.stream?.getTracks().forEach(t=>t.stop());document.getElementById("callVideos")?.replaceChildren();try{await FB.groupCallLeave(old.gid)}catch(e){console.warn("Qoʻngʻiroqdan chiqish:",e)}if(!silent&&st.chat?.id===old.gid)draw()}

function scheduleMeta(){const visible=$("scheduleVisible")?.value,expires=$("scheduleExpires")?.value;const visibleAt=visible?new Date(visible).getTime():0,expiresAt=expires?new Date(expires).getTime():0;if(visibleAt&&(!Number.isFinite(visibleAt)||visibleAt<Date.now()-60000||visibleAt>Date.now()+30*864e5))throw new Error("Koʻrinish vaqti hozirdan 30 kun ichida boʻlishi kerak.");if(expiresAt&&(!Number.isFinite(expiresAt)||expiresAt<=Math.max(Date.now(),visibleAt)))throw new Error("Yashirish vaqti koʻrinish vaqtidan keyin boʻlishi kerak.");if(visibleAt&&expiresAt&&expiresAt<=visibleAt)throw new Error("Yashirish vaqti keyinroq boʻlishi kerak.");return{...(visibleAt?{visibleAt}:{}),...(expiresAt?{expiresAt}:{})}}
function toggleSchedule(){st.scheduleOpen=!st.scheduleOpen;draw()}
function send(){const i=$("mi"),v=i.value.trim();if(!v||st.chat?.obs)return;const ch=st.chat;let meta={};try{meta=ch.t==="g"?scheduleMeta():{}}catch(x){uiAlert(x.message||String(x));return}i.value="";i.focus();["scheduleVisible","scheduleExpires"].forEach(k=>{const e=$(k);if(e)e.value=""});FB.send(ch.t=="g"?"groups":"chats",ch.id,v,st.user.name,null,meta).catch(x=>{const e=$("mi");if(e&&!e.value)e.value=v;uiAlert("Xabar yuborilmadi: "+(x.message||x))})}
function privV(){if(!st.user)return"";return `<h3>Shaxsiy rasmlarim</h3><p class="sub" style="text-align:left;font-size:12px;margin:0 0 8px">Faqat rasm qoʻllanadi (3 tagacha). Suhbatda uch nuqta → “Ruxsatni bekor qilish” orqali kirishni toʻxtatasiz. Video hozircha shaxsiy profilga yuklanmaydi.</p><div class="ph" style="padding:0">${st.priv.map((x,i)=>`<div style="position:relative"><img src="${x}"><button onclick="delPriv(${i})" style="position:absolute;top:-6px;right:-6px;width:22px;height:22px;border-radius:50%;background:#e5554a;color:#fff;display:grid;place-items:center">${I("x",12)}</button></div>`).join("")}${st.priv.length<3?`<div onclick="$('pp').click()">${I("plus",24)}</div>`:""}</div><input type="file" id="pp" accept="image/*" hidden onchange="addPriv(this)">`}
function addPriv(i){const f=i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=async()=>{const c=document.createElement("canvas"),k=Math.min(1,480/Math.max(im.width,im.height));c.width=im.width*k;c.height=im.height*k;c.getContext("2d").drawImage(im,0,0,c.width,c.height);const n=[...st.priv,c.toDataURL("image/jpeg",.7)];try{await FB.setPriv(n);st.priv=n;draw()}catch(x){uiAlert("Rasm saqlanmadi: "+x.message)}};im.src=r.result};r.readAsDataURL(f)}
async function delPriv(i){const n=st.priv.filter((_,j)=>j!=i);try{await FB.setPriv(n);st.priv=n;draw()}catch(x){uiAlert(x.message)}}

const INTS=["Sayohat","Sport","Kitob","Musiqa","Oshpazlik","Texnologiya","Biznes","Sanʼat","Tabiat","Dinu maʼnaviyat","Oila","Kino","Moda","Avtomobil"];
Object.assign(st,{sw:false,swiped:{},deck:[],di:0,sv:null,csh:{}});
function togInt(x){keep();const a=st.p.ints=st.p.ints||[],i=a.indexOf(x);if(i>=0)a.splice(i,1);else if(a.length<5)a.push(x);draw()}
function toast(m){const d=document.createElement("div");d.className="toast";d.textContent=m;document.body.appendChild(d);setTimeout(()=>d.remove(),1700)}
/* soʻrovnoma */
function surveyV(){const pr=st.user.prefs||{},s=st.sv=st.sv||{g:pr.g||"erkak",age:pr.age||"",vil:pr.vil||PL[0][0],reg:pr.reg||"",ints:[...(pr.ints||[])],pur:pr.pur||"oila",disability:!!pr.disability,disabilityType:pr.disabilityType||"",disabilityNote:pr.disabilityNote||""},L=(PL.find(x=>x[0]==s.vil)||PL[0])[1];if(!L.some(x=>x[0]==s.reg))s.reg=L[0][0];
 return `<div class="ov"><div class="hd"><button onclick="svSkip()">${I("x",22)}</button><b>Qisqa soʻrovnoma</b></div><div class="sheet"><p class="sub" style="text-align:left">Sizga mos nomzodlarni tavsiya qilish uchun bir daqiqa vaqt ajrating.</p>
<label>Jinsingiz</label><div class="seg"><button class="${s.g=="erkak"?"on":""}" onclick="svs('g','erkak')">Erkak</button><button class="${s.g=="ayol"?"on":""}" onclick="svs('g','ayol')">Ayol</button></div>
<label>Yoshingiz</label><input class="in" type="number" value="${s.age}" oninput="st.sv.age=+this.value">
<label>Yashash joyingiz</label><select class="in" onchange="svs('vil',this.value)">${PL.map(x=>`<option ${x[0]==s.vil?"selected":""}>${x[0]}</option>`).join("")}</select><select class="in" style="margin-top:8px" onchange="st.sv.reg=this.value">${L.map(x=>`<option ${x[0]==s.reg?"selected":""}>${x[0]}</option>`).join("")}</select>
<label style="display:flex;align-items:center;gap:10px;margin-top:14px"><input type="checkbox" ${s.disability?"checked":""} onchange="svs('disability',this.checked)"> ♿ Imkoniyati cheklanganman / nogironligim bor</label>${s.disability?`<label>Holatingiz (ixtiyoriy)</label><select class="in" onchange="svs('disabilityType',this.value)"><option value="">Koʻrsatmaslik</option><option value="limited" ${s.disabilityType==="limited"?"selected":""}>Imkoniyati cheklangan (batafsil aytmayman)</option><option value="speech" ${s.disabilityType==="speech"?"selected":""}>Gapirishda qiyinchilik bor</option><option value="hearing" ${s.disabilityType==="hearing"?"selected":""}>Eshitishida cheklov bor</option><option value="mobility" ${s.disabilityType==="mobility"?"selected":""}>Yurishda / harakatlanishda qiyinchilik bor</option><option value="vision" ${s.disabilityType==="vision"?"selected":""}>Koʻrishida cheklov bor</option><option value="other" ${s.disabilityType==="other"?"selected":""}>Boshqa holat</option></select><label>Qoʻshimcha izoh (ixtiyoriy)</label><textarea class="in" rows="2" placeholder="Istasangiz, qisqacha yozing" oninput="st.sv.disabilityNote=this.value">${esc(s.disabilityNote||"")}</textarea>`:""}<label>Qiziqishlaringiz (6 tagacha)</label><div class="ints">${INTS.map(x=>`<button class="ichip ${s.ints.includes(x)?"on":""}" onclick="svi('${x}')">${x}</button>`).join("")}</div>
<label>Maqsadingiz</label><div class="seg pur">${Object.keys(PUR).map(k=>`<button class="${s.pur==k?"on":""}" onclick="svs('pur','${k}')">${PUR[k][2]}</button>`).join("")}</div>
<button class="go" style="width:100%;margin-top:18px" onclick="svSave()">Saqlash</button><button class="ghost" style="width:100%;margin-top:8px" onclick="svSkip()">Keyinroq</button></div></div>`}
function svs(k,v){st.sv[k]=v;draw()}
function svi(x){const a=st.sv.ints,i=a.indexOf(x);if(i>=0)a.splice(i,1);else if(a.length<6)a.push(x);draw()}
