function score(a,pr){let s=0;if(a.reg==pr.reg)s+=45;else if(vilOf(a)==pr.vil)s+=25;s+=((a.ints||[]).filter(x=>(pr.ints||[]).includes(x)).length)*12;if(pr.pur&&a.pur==pr.pur)s+=15;if(pr.disability&&a.disability)s+=25;if(pr.disability&&pr.disabilityType&&pr.disabilityType!=="limited"&&a.profileDetails?.disabilityType===pr.disabilityType)s+=15;const d=Math.abs((a.age||0)-(pr.age||a.age||0));s+=d<=3?10:d<=7?5:0;return s}
function pool(){const pr=st.user.prefs,tg=pr.g=="erkak"?"kelin":"kuyov";return st.ads.filter(a=>!a.anon&&a.img&&(a.uid!=st.user.uid||a.isDemo)&&a.g==tg&&!(a.id in st.swiped)).map(a=>({a,s:score(a,pr)+Math.random()*3})).sort((x,y)=>y.s-x.s).map(x=>x.a)}
