function stamp(el,dx){el.querySelector(".like").style.opacity=Math.max(0,Math.min(1,dx/100));el.querySelector(".nope").style.opacity=Math.max(0,Math.min(1,-dx/100))}
let ignoreSwipeClick=false;
function bindSwipe(){const el=$("sc");if(!el)return;let x0=0,dx=0,on=false;
 el.onpointerdown=e=>{on=true;x0=e.clientX;dx=0;el.setPointerCapture(e.pointerId);el.style.transition="none"};
 el.onpointermove=e=>{if(!on)return;dx=e.clientX-x0;if(Math.abs(dx)>8){ignoreSwipeClick=true;setTimeout(()=>{ignoreSwipeClick=false},450)}el.style.transform=`translateX(${dx}px) rotate(${dx/18}deg)`;stamp(el,dx)};
 const end=()=>{if(!on)return;on=false;if(Math.abs(dx)>100)fly(dx>0?1:0);else{el.style.transition="transform .25s";el.style.transform="";stamp(el,0)}};
 el.onpointerup=end;el.onpointercancel=end}
let flying=false;
function fly(v){const el=$("sc");if(!el||flying)return;flying=true;stamp(el,v?200:-200);el.style.transition="transform .3s,opacity .3s";el.style.transform=`translateX(${v?650:-650}px) rotate(${v?30:-30}deg)`;el.style.opacity=0;setTimeout(()=>{flying=false;decide(v)},280)}
async function decide(v){const a=st.deck[st.di];if(!a)return;st.di++;renderDeck();st.swiped[a.id]=v;
 try{await FB.swipe(a,v);if(v){if(!st.fav.includes(a.id)){st.fav.push(a.id);save();FB.saveUser({favs:st.fav}).catch(()=>{})}toast("Yurak yuborildi, sevimlilarga qoʻshildi");await FB.like(a,st.user)}}catch(x){console.error(x)}}
function svReset(){for(const k in st.swiped)if(st.swiped[k]===0)delete st.swiped[k];st.deck=pool();st.di=0;renderDeck()}

let MKL;
const pcol={color:"#f0b34a",fillOpacity:.2};
const mkPoly=P=>P.length>2?L.polygon(P,pcol):L.polyline(P,pcol);
function drawMarkers(){if(!MAP||!window.L)return;if(MKL)MKL.remove();MKL=L.layerGroup().addTo(MAP);const g={};list().forEach(a=>{const p=pl(a.reg);if(p)(g[p.lat+","+p.lng]=g[p.lat+","+p.lng]||[]).push(a)});Object.entries(g).forEach(([n,l])=>{const p=n.split(",").map(Number);if(st.areaGeo&&!geoHasPoint(st.areaGeo,p[0],p[1]))return;const d=st.myLoc?distanceKm(st.myLoc.lat,st.myLoc.lng,p[0],p[1]):null,dt=d==null?"":(d<1?Math.round(d*1000)+" m":(d<10?d.toFixed(1):Math.round(d))+" km"),ages=l.map(a=>Number(a.age)).filter(a=>Number.isFinite(a)&&a>0).sort((a,b)=>a-b),ageLabel=ages.length===0?"Nomzod":ages.length===1?ages[0]+" yosh":ages.length<=3?ages.join(" · "):ages.slice(0,3).join(" · ")+" +"+(ages.length-3),ageTitle="Nomzodlar yoshi: "+(ages.length?ages.join(", "):"koʻrsatilmagan");L.marker(p,{icon:L.divIcon({className:"",html:`<div class="mk-wrap"><div class="mk mk-age" title="${ageTitle}">${ageLabel}</div>${dt?`<span class="mk-distance">${dt}</span>`:""}</div>`,iconSize:[Math.max(58,ageLabel.length*8+20,dt.length*7+20),dt?58:38],iconAnchor:[Math.max(29,ageLabel.length*4+10),dt?22:19]}),title:ageTitle}).addTo(MKL).on("click",()=>{if(!st.dr.on)showPlace(n)})});if(st.myLoc)showMyLocation();polyRes()}
function initMap(){const el=$("map");if(!el)return;
 if(!window.L){el.innerHTML='<div class="empty">Xarita kutubxonasi yuklanmadi. Internetni tekshiring va sahifani yangilang.</div>';return}
 try{
  if(MAP){try{MAP.off();MAP.remove()}catch(e){}MAP=null;MKL=null;DL=null;MYL=null;MYC=null}
  const m=MAP=L.map(el,{zoomControl:true}).setView(st.mv||[41.3,64.6],st.mz||5);
  const T=[["https://tile.openstreetmap.org/{z}/{x}/{y}.png","© OpenStreetMap contributors"],["https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png","© OpenStreetMap © CARTO"]];
  let prov=0,fails=0,layer;
  const addT=()=>{fails=0;layer=L.tileLayer(T[prov][0],{maxZoom:18,attribution:T[prov][1]});layer.on("tileerror",()=>{if(++fails>=4&&prov===0){prov=1;try{m.removeLayer(layer)}catch(e){}addT()}});layer.addTo(m)};
  addT();
  const locate=L.control({position:"bottomright"});
  locate.onAdd=()=>{const box=L.DomUtil.create("div","leaflet-bar yaqin-locate-control");box.innerHTML='<button type="button" aria-label="Mening joyim" title="Mening joyim">'+I("pin",19)+'</button>';L.DomEvent.disableClickPropagation(box);L.DomEvent.on(box.querySelector("button"),"click",e=>{L.DomEvent.stop(e);getMyLocation()});return box};
  locate.addTo(m);
  drawMarkers();
  const P=st.dr.pts;if(P.length)DL=mkPoly(P).addTo(m);if(st.areaGeo){DL=L.geoJSON(st.areaGeo,{style:{color:"#43a5ff",weight:3,fillColor:"#43a5ff",fillOpacity:.10}}).addTo(m);m.fitBounds(DL.getBounds(),{padding:[20,20],maxZoom:st.areaDistrict?12:8});}
  m.on("click",e=>{if(!st.dr.on)return;st.dr.pts.push([e.latlng.lat,e.latlng.lng]);if(DL)m.removeLayer(DL);DL=mkPoly(st.dr.pts).addTo(m);polyRes()});
  m.on("moveend",()=>{st.mv=[m.getCenter().lat,m.getCenter().lng];st.mz=m.getZoom()});
  if(st.myLoc){showMyLocation();m.setView([st.myLoc.lat,st.myLoc.lng],Math.max(m.getZoom(),12))}
  setTimeout(()=>{if(MAP===m)m.invalidateSize()},250)
 }catch(e){el.innerHTML='<div class="empty">Xarita xatosi: '+esc(e.message)+'</div>'}}

