/* admin panel */
async function openAdmin(){st.form="admin";st.ap.tab=st.ap.tab||"pay";draw();try{st.ap.stats=await FB.counts();if(st.form=="admin")draw()}catch(x){console.error(x)}}
async function adminGroupPremium(id,days){const g=st.groups.find(x=>x.id===id);if(!g)return;if(!await uiConfirm(days===0?"Ushbu guruhning premiumini hozir oʻchirasizmi?":"Guruh premium muddatiga "+days+" kun qoʻshilsinmi?","Premium boshqaruvi",days===0))return;try{await FB.adminSetGroupPremium(id,days===0?0:Math.max(Date.now(),Number(g.premiumUntil)||0)+days*864e5);toast(days===0?"Premium oʻchirildi":"Premium muddati yangilandi");if(st.form==="admin")draw()}catch(e){uiAlert("Premiumni oʻzgartirib boʻlmadi: "+(e.message||e))}}
async function reviewAd(id,status){const a=st.raw.find(x=>x.id==id);if(!a)return;const active=status=="active";if(!await uiConfirm(active?"Eʼlon faollashtirilsinmi?":"Eʼlon rad etilsinmi?",active?"Tasdiqlash":"Rad etish",!active))return;try{await FB.upAd(id,{status,t:Date.now()});toast(active?"Eʼlon tasdiqlandi":"Eʼlon rad etildi")}catch(x){uiAlert("Amal bajarilmadi: "+x.message)}}
async function payDo(id,ok){const p=st.pays.find(x=>x.id==id);if(!p)return;if(!await uiConfirm(ok?`${fmt(p.amount)} soʻm toʻlov tasdiqlansinmi? Eʼlon avtomatik yangilanadi.`:"Toʻlov rad etilsinmi?",ok?"Tasdiqlash":"Rad etish",!ok))return;try{await FB.decide(p,ok);toast(ok?"Tasdiqlandi":"Rad etildi")}catch(x){uiAlert("Amal bajarilmadi: "+x.message)}}
async function saveSet(){const g=i=>$(i).value.trim(),cards=[1,2].map(n=>({type:g("ct"+n),number:g("cn"+n),holder:g("ch"+n)})).filter(c=>c.number),n=i=>+g(i)||0;if(!n("pa")||!n("pv")||!n("pr")){uiAlert("Narxlarni toʻgʻri kiriting");return}try{await FB.saveSettings({phone:g("sph"),cards,prices:{ad:n("pa"),vip:n("pv"),raise:n("pr")}});toast("Sozlamalar saqlandi")}catch(x){uiAlert("Saqlanmadi: "+x.message)}}
async function repAdDel(rid,aid){if(!await uiConfirm("Shikoyat qilingan eʼlon butunlay oʻchirilsinmi?","Oʻchirish",true))return;try{await FB.delAd(aid);await FB.delReport(rid);toast("Eʼlon oʻchirildi")}catch(x){uiAlert(x.message)}}
async function repDel(id){try{await FB.delReport(id)}catch(x){uiAlert(x.message)}}
const demoTag=a=>a.isDemo&&(st.admin||window.YQ_DEMO_PUBLIC_BADGE)?'<span class="tag" style="background:#7c3aed;color:#fff">Namuna</span> ':"";
async function demoLoad(){try{st.ap.demo=await FB.demoCount()}catch(e){st.ap.demo="—"}if(st.form=="admin")draw()}
async function demoAdd(){const f=fb();if(!f)return;const ex=Number(st.ap.demo)||0;if(!await uiConfirm((ex?"Allaqachon "+ex+" ta namuna eʼlon bor. ":"")+"56 ta namuna eʼlon (28 kelin, 28 kuyov) qoʻshilsinmi?","Qoʻshish"))return;try{const n=await f.seedDemo(yqDemoAds(pl));toast(n+" ta namuna eʼlon qoʻshildi");demoLoad()}catch(x){uiAlert("Qoʻshilmadi: "+x.message)}}
async function demoDel(){const f=fb();if(!f)return;if(!await uiConfirm("Barcha namuna eʼlonlar oʻchirilsinmi? Bu amalni qaytarib boʻlmaydi.","Oʻchirish"))return;try{const n=await f.delDemo();toast(n+" ta namuna eʼlon oʻchirildi");demoLoad()}catch(x){uiAlert("Oʻchmadi: "+x.message)}}
function adminV(){const A=st.ap,P=st.pays,S=A.stats||{},sc=(n,l)=>`<div class="price" style="text-align:center;margin:0;padding:10px 4px"><b style="font-size:20px;color:var(--a)">${n??"…"}</b><p style="color:var(--m);font-size:11px">${l}</p></div>`;let b="";
 if(A.tab=="pay")b=[...P.filter(x=>x.status=="pending"),...P.filter(x=>x.status!="pending")].map(x=>`<div class="card" style="display:block"><b>${esc(x.name||"")}</b> <span class="tag">${KIND[x.kind]||x.kind}</span><p>${esc(x.email||"")}</p><p><b style="color:var(--a)">${fmt(x.amount)} soʻm</b> · kod ${esc(x.id.slice(-6).toUpperCase())} · ${new Date(x.t).toLocaleString("uz")}</p>${x.status=="pending"?`<div class="acts"><button class="go" onclick="payDo('${x.id}',true)">Tasdiqlash</button><button class="ghost" onclick="payDo('${x.id}',false)">Rad etish</button></div>`:`<span class="tag">${PSTAT[x.status]}</span>`}</div>`).join("")||'<div class="empty">Toʻlov soʻrovlari yoʻq</div>';
 else if(A.tab=="ads")b=st.raw.map(a=>`<div class="card"><div class="av">${av(a)}</div><div class="inf"><b>${esc(a.anon?"Anonim":a.name)}, ${a.age}</b> ${demoTag(a)}${a.status=="pending"?'<span class="tag">Kutilmoqda</span>':""}${a.vip?'<span class="tag vt">VIP</span>':""}<p>${esc(a.reg)}</p><div class="acts"><button class="ghost" style="color:#e5554a" onclick="reviewAd('${a.id}','active')">Tasdiqlash</button><button class="ghost" onclick="reviewAd('${a.id}','rejected')">Rad etish</button><button class="ghost" style="color:#e5554a" onclick="delAd('${a.id}')">${I("x",14)} Oʻchirish</button></div></div></div>`).join("")||'<div class="empty">Eʼlonlar yoʻq</div>';
 else if(A.tab=="demo")b=`<div class="card" style="display:block"><b>Namuna eʼlonlar</b><p>Hozirgi namuna eʼlonlar: <b style="color:var(--a)">${A.demo??"…"}</b></p><p style="margin-top:8px">Bir bosishda 56 ta (28 kelin, 28 kuyov) namuna eʼlon qoʻshiladi: turli hududlar, yosh, maqsad va avatarlar. Anonim va VIP namunalar ham bor. "Namuna" belgisi faqat sizga koʻrinadi, ularga yozilgan xabarlar sizga (admin) keladi.</p><div class="acts"><button class="go" onclick="demoAdd()">Namuna qoʻshish</button><button class="ghost" style="color:#e5554a" onclick="demoDel()">Barchasini oʻchirish</button></div></div>`;
 else if(A.tab=="sup")b=st.threads.map(t=>`<div class="card" style="align-items:center" onclick="openSupA('${t.uid}')"><div class="av">${I("user",24)}</div><div class="inf"><b>${esc(t.name||"Foydalanuvchi")}</b><p>${esc(t.last||"")}</p><small style="color:var(--m)">${ago(t.lastT)}</small></div>${t.lastBy=="user"&&t.lastT>(st.seen["sup_"+t.uid]||0)?'<span class="dot"></span>':""}</div>`).join("")||'<div class="empty">Yordamga yozishmalar yoʻq</div>';
 else if(A.tab=="rep")b=A.reps.map(r=>`<div class="card" style="align-items:center"><div class="inf"><b>${r.ad?"Eʼlonga shikoyat":"Suhbatga shikoyat"}${r.adName?": "+esc(r.adName):""}</b><p>${r.reason?esc(r.reason)+" · ":""}${r.ad?"Eʼlon "+esc(String(r.ad).slice(-6)):"Suhbat "+esc(String(r.chat).slice(-8))} · ${new Date(r.t).toLocaleString("uz")}</p>${r.ad?`<div class="acts"><button class="ghost" style="color:#e5554a" onclick="repAdDel('${r.id}','${r.ad}')">Eʼlonni oʻchirish</button></div>`:""}</div><button class="ghost" onclick="repDel('${r.id}')">${I("x",14)}</button></div>`).join("")||'<div class="empty">Shikoyatlar yoʻq</div>';
 else if(A.tab=="groups")b=st.groups.map(g=>{const until=Number(g.premiumUntil)||0,active=until>Date.now();return `<div class="card" style="display:block"><b>${esc(g.name||"Guruh")}</b><p>Egasi: ${esc(g.owner||"—")} · ${g.n||1} aʼzo</p><p>${active?"Premium muddati: "+new Date(until).toLocaleString("uz"):"Premium faol emas"}</p><div class="acts"><button class="go" onclick="adminGroupPremium('${g.id}',30)">+30 kun</button><button class="ghost" onclick="adminGroupPremium('${g.id}',90)">+90 kun</button><button class="ghost" style="color:#e5554a" onclick="adminGroupPremium('${g.id}',0)">Premiumni oʻchirish</button></div></div>`}).join("")||'<div class="empty">Guruhlar topilmadi</div>';
 else{const c=st.cfg.cards||[],f=(n,x)=>`<label>${n}-karta</label><input class="in" id="ct${n}" placeholder="UZCARD yoki HUMO" value="${esc((c[n-1]||{}).type||"")}" style="margin-bottom:6px"><input class="in" id="cn${n}" placeholder="Karta raqami" inputmode="numeric" value="${esc((c[n-1]||{}).number||"")}" style="margin-bottom:6px"><input class="in" id="ch${n}" placeholder="Karta egasi" value="${esc((c[n-1]||{}).holder||"")}">`;b=`${f(1)}${f(2)}<label>Ishonch telefoni (Yordam xizmatida koʻrinadi)</label><input class="in" id="sph" placeholder="+998 90 123 45 67" value="${esc(st.cfg.phone||"")}"><label>Narxlar (soʻm)</label><input class="in" id="pa" type="number" placeholder="Qoʻshimcha eʼlon" value="${PR.ad}" style="margin-bottom:6px"><input class="in" id="pv" type="number" placeholder="VIP TOP" value="${PR.vip}" style="margin-bottom:6px"><input class="in" id="pr" type="number" placeholder="Yuqoriga koʻtarish" value="${PR.raise}"><button class="go" style="width:100%;margin-top:16px" onclick="saveSet()">Saqlash</button><div class="card" style="margin-top:16px;align-items:center" onclick="openLegal()"><div class="inf"><b>Rasmiy soʻrovlar</b><p>Vakolatli organlar soʻrovi boʻyicha maʼlumot tayyorlash va jurnal</p></div></div>`}
 return `<div class="ov"><div class="hd"><button onclick="st.form=null;draw()">${I("back",22)}</button><b>Admin panel</b></div><div class="sheet"><div class="row">${sc(S.users,"Foydalanuvchi")}${sc(S.ads,"Eʼlon")}${sc(P.filter(x=>x.status=="pending").length,"Kutilayotgan")}${sc(A.reps.length,"Shikoyat")}</div><div class="seg" style="margin:12px 0">${[["pay","Toʻlov"],["ads","Eʼlon"],["groups","Guruh"],["demo","Namuna"],["sup","Yordam"+(supUn()?" ("+supUn()+")":"")],["rep","Shikoyat"],["set","Sozlama"]].map(t=>`<button class="${A.tab==t[0]?"on":""}" style="font-size:12px;padding:11px 2px" onclick="st.ap.tab='${t[0]}';draw()${t[0]=='demo'?';demoLoad()':''}">${t[1]}</button>`).join("")}</div>${b}</div></div>`}

/* ===== bildirishnomalar va yordam xizmati ===== */
Object.assign(st,{notifs:[],nnew:{},thread:null,threads:[],sup:null,sm:[]});
let UN,UT,UTH,USM,nFirst=1;
const ago=t=>{const s=(Date.now()-t)/1000;return s<60?"hozir":s<3600?Math.floor(s/60)+" daq oldin":s<86400?Math.floor(s/3600)+" soat oldin":new Date(t).toLocaleDateString("uz")};
const unN=()=>st.notifs.filter(n=>!n.read).length;
const supDot=()=>!!(st.thread&&st.thread.lastBy=="admin"&&st.thread.lastT>(st.seen.sup_me||0));
const supUn=()=>st.threads.filter(t=>t.lastBy=="user"&&t.lastT>(st.seen["sup_"+t.uid]||0)).length;
function updBadges(){const b=$("nb"),d=$("sd");if(b){b.style.display=unN()?"block":"none";b.textContent=unN()>9?"9+":unN()}if(d)d.style.display=supDot()?"block":"none"}
function stopAll(){[UC,UG,UA1,UA2,UPY,US,UN,UT,UTH,USM,US_].forEach(f=>f&&f());UC=UG=UA1=UA2=UPY=US=UN=UT=UTH=USM=US_=null;closeCh();st.chats=[];st.groups=[];st.priv=[];st.mypays=[];st.pays=[];st.admin=false;st.notifs=[];st.thread=null;st.threads=[]}
function sysNotif(n){if(!("Notification" in window)||Notification.permission!="granted")return;const o={body:n.text||"",icon:"icons/icon-192.png",badge:"icons/icon-192.png",tag:n.id};(navigator.serviceWorker?navigator.serviceWorker.ready.then(r=>r.showNotification(n.title,o)):Promise.reject()).catch(()=>{try{new Notification(n.title,o)}catch(e){}})}
async function enablePush(){if(!("Notification" in window)){uiAlert("Brauzeringiz bildirishnomalarni qoʻllamaydi");return}const r=await Notification.requestPermission();toast(r=="granted"?"Telefon bildirishnomalari yoqildi":"Ruxsat berilmadi");draw()}
addEventListener("fb-ready",()=>{FB.onUser(u=>{if(!u){st.nFor=null;return}if(st.nFor==u.uid)return;st.nFor=u.uid;nFirst=1;
 UN=FB.notifs(u.uid,(l,added)=>{st.notifs=l;if(added.length){added.forEach(n=>{if(!n.read){sysNotif(n);if(st.form=="notif"){st.nnew[n.id]=1}else toast(n.title)}});if(st.form=="notif")FB.markRead(added.filter(n=>!n.read).map(n=>n.id)).catch(()=>{})}if(st.form=="notif")draw();else updBadges()});
 US_=FB.supThread(u.uid,t=>{st.thread=t;updBadges()});
 FB.isAdmin().then(v=>{if(v)UT=FB.threads(l=>{st.threads=l;if(st.form=="admin"&&st.ap.tab=="sup")draw()})})})});
var US_;
function openNotif(){if(!need())return;st.nnew={};const ids=st.notifs.filter(n=>!n.read).map(n=>n.id);ids.forEach(i=>st.nnew[i]=1);if(ids.length)FB.markRead(ids).catch(()=>{});st.form="notif";draw()}
function closeNotif(){st.form=null;st.nnew={};draw()}
function readAll(){const ids=st.notifs.filter(n=>!n.read).map(n=>n.id);if(ids.length)FB.markRead(ids).catch(()=>{});st.nnew={};draw()}
function ntGo(t){st.form=null;st.nnew={};if(t=="support"){openSup(st.user.uid);return}st.tab=t=="like"?"msg":t=="match"?"home":"prof";draw()}
function notifV(){const L=[...st.notifs].sort((a,b)=>b.t-a.t).slice(0,60),isN=n=>st.nnew[n.id]||!n.read,nw=L.filter(isN),old=L.filter(n=>!isN(n));
 const row=(n,y)=>`<div class="nt ${y?"new":""}" onclick="ntGo('${n.type}')">${y?'<span class="dot"></span>':'<span style="width:10px;flex:none"></span>'}<div><b>${esc(n.title)}</b><p>${esc(n.text||"")}</p><small>${ago(n.t)}</small></div></div>`;
 const perm="Notification" in window&&Notification.permission!="granted"?`<div class="cons" style="margin:0 0 12px"><b>Telefon bildirishnomalarini yoqing</b><p style="color:var(--m);margin:4px 0 8px;font-size:13px">Ilova ochiq yoki orqa fonda turganda yangi xabar haqida bildirishnoma keladi.</p><button class="go" onclick="enablePush()">Yoqish</button></div>`:"";
 return `<div class="ov"><div class="hd"><button onclick="closeNotif()">${I("back",22)}</button><b>Bildirishnomalar</b>${nw.length?`<button onclick="readAll()" style="font-size:12px;color:var(--a)">Barchasi oʻqildi</button>`:""}</div><div class="sheet">${perm}${nw.length?`<div class="nh">YANGI · ${nw.length}</div>${nw.map(n=>row(n,1)).join("")}`:""}${old.length?`<div class="nh">OLDINGI</div>${old.map(n=>row(n,0)).join("")}`:""}${L.length?"":'<div class="empty">Hozircha bildirishnoma yoʻq</div>'}</div></div>`}
function openSup(uid,meta){if(!need())return;closeSupL();st.sup={uid,admin:!!meta,...(meta||{})};st.sm=[];USM=FB.supMsgs(uid,m=>{st.sm=m;supRender();supSeen()});st.form="support";draw()}
function openSupA(uid){const t=st.threads.find(x=>x.uid==uid)||{};openSup(uid,{name:t.name,email:t.email,contact:t.contact})}
function closeSupL(){USM&&USM();USM=null}
function closeSup(){const a=st.sup&&st.sup.admin;closeSupL();st.form=a?"admin":null;st.sup=null;draw()}
function supSeen(){if(!st.sup)return;st.seen[st.sup.admin?"sup_"+st.sup.uid:"sup_me"]=Date.now();save();updBadges()}
function supRender(){const m=$("sms");if(!m||!st.sup)return;const a=st.sup.admin;m.innerHTML=st.sm.length?st.sm.map(x=>{const me=a?x.from=="admin":x.from=="user";return `<div class="m ${me?"me":""}">${!me&&!a?'<b>Yordam xizmati</b>':""}${esc(x.text)}<small>${tm(x.t)}</small></div>`}).join(""):`<div class="empty">${a?"Yozishma yoʻq":"Savolingizni yozing, admin tez orada javob beradi."}</div>`;m.scrollTop=m.scrollHeight}
async function supSend(){const i=$("smi"),v=i.value.trim();if(!v)return;i.value="";try{await FB.supSend(st.sup.uid,v,st.sup.admin?"admin":"user",st.user)}catch(x){i.value=v;uiAlert("Xabar yuborilmadi: "+x.message)}}
function supV(){const S=st.sup||{},a=S.admin,ph=st.cfg.phone;return `<div class="ov"><div class="hd"><button onclick="closeSup()">${I("back",22)}</button><b>${a?esc(S.name||"Foydalanuvchi"):"Yordam xizmati"}</b></div>${a?`<p class="sub" style="text-align:left;padding:8px 14px 0;margin:0">${esc(S.email||"")}${S.contact?" · "+esc(S.contact):""}</p>`:(ph?`<div class="box" style="margin:10px 12px 0"><b>${I("phone",16)} Ishonch telefoni</b><div style="font-size:22px;font-weight:800;margin:6px 0 10px">${esc(ph)}</div><a class="go" style="display:block;text-align:center;text-decoration:none" href="tel:${esc(ph.replace(/[^\d+]/g,""))}">Qoʻngʻiroq qilish</a></div>`:"")}<div class="msgs" id="sms"></div><div class="send"><input class="in" id="smi" maxlength="1000" placeholder="${a?"Javob yozing..":"Xabaringizni yozing.."}" autocomplete="off" onkeydown="if(event.key=='Enter')supSend()"><button class="go" onclick="supSend()">${I("send",18)}</button></div></div>`}
const oldProf=prof;
prof=function(){const h=oldProf();if(!st.user)return h;const n=unN(),menu=`<div class="card" style="align-items:center" onclick="openNotif()"><div class="av">${I("bell",26)}</div><div class="inf"><b>Bildirishnomalar</b><p>${n?n+" ta yangi":"Yangi bildirishnoma yoʻq"}</p></div>${n?`<span class="tag" style="background:#e5554a;color:#fff;font-weight:800">${n}</span>`:""}</div><div class="card" style="align-items:center" onclick="openSup(st.user.uid)"><div class="av">${I("headset",26)}</div><div class="inf"><b>Yordam xizmati</b><p>Admin bilan yozishma</p></div>${supDot()?'<span class="dot"></span>':""}</div>`;return h.replace("<h3>Toʻlovlarim</h3>",menu+"<h3>Toʻlovlarim</h3>")};

/* ===== bloklash va push roʻyxatdan oʻtkazish ===== */
Object.assign(st,{bl:[],blby:[]});let UB1,UB2;
const badSet=()=>new Set([...st.bl.map(b=>b.to),...st.blby]);
function syncAds(){const me=st.user&&st.user.uid,now=Date.now(),bad=badSet(),m=a=>({...a,mine:!!me&&a.uid==me,vip:!!a.vip&&(!a.vipUntil||a.vipUntil>now)});st.mine=st.raw.filter(a=>me&&a.uid==me).map(m);st.ads=st.raw.filter(a=>a.status!="pending"&&!bad.has(a.uid)).map(m)}
function otherUid(c){return c.owner==st.user.uid?c.asker:c.owner}
const oldMsgs=msgs;
msgs=function(){const all=st.chats,bad=badSet();st.chats=all.filter(c=>!bad.has(otherUid(c)));try{return oldMsgs()}finally{st.chats=all}};
async function blockU(){const c=st.chats.find(x=>x.id==(st.chat&&st.chat.id));if(!c)return;st.menu=false;const to=otherUid(c),nm=c.owner==st.user.uid?c.askerName:c.ownerName;
 if(!await uiConfirm(`${nm} bloklansinmi? U sizga yoza olmaydi, eʼlonlarini ham koʻrmaysiz.`,"Bloklash",true)){draw();return}
 try{await FB.block(to,nm);closeChat();toast("Foydalanuvchi bloklandi")}catch(x){uiAlert("Bloklanmadi: "+x.message)}}
async function unblock(to){try{await FB.unblock(to);toast("Blokdan chiqarildi")}catch(x){uiAlert(x.message)}}
